import React from "react";
import {
  act,
  createEvent,
  fireEvent,
  render,
  screen,
  within,
  RenderResult,
} from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./ComboBox.stories";
import ComboBox, { ComboBoxDefaultOption } from ".";

const { Basic } = composeStories(stories) as any;

const options = [
  { label: "Rust", value: "rust" },
  { label: "Elixir", value: "elixir" },
  { label: "Kotlin", value: "kotlin" },
  { label: "JavaScript", value: "js", disabled: true },
  { label: "Elm", value: "elm" },
  { label: "Scala", value: "scala" },
];

// test util
const renderComboBox = (props: any, rerender?: any) => {
  const wrapper: RenderResult = rerender
    ? rerender(<ComboBox {...props} />)
    : render(<ComboBox {...props} />);

  const input = screen.getByRole("combobox") as HTMLInputElement;
  const toggleButton = screen.getByRole("button", { name: /toggle menu/i });
  return {
    ...wrapper,
    input,
    toggleButton,
    clear: () => {
      input.focus();
      fireEvent.click(screen.getByRole("button", { name: /clear input/i }));
    },
    clearInput: () => {
      fireEvent.change(input, { target: { value: "" } });
      expect(input).toHaveValue("");
    },
    focusWithMouse: () => {
      fireEvent.click(input);
    },
    getOption: (name: string) => screen.getByRole("option", { name }),
    getOptionByIdx: (index: number) => screen.getAllByRole("checkbox")[index],
    clickOnRemove: (name: string) => {
      const chip = Array.from(
        // eslint-disable-next-line testing-library/no-node-access
        wrapper.container.querySelectorAll(".ds-chip") as NodeList
      ).find((el: Node) => el.textContent === name) as HTMLElement;
      const removeBtn = within(chip).getByRole("button", { name: "Remove" });
      fireEvent.click(removeBtn);
    },
    clickOnToggleButton: async () => {
      fireEvent.click(toggleButton);
    },
    expectMenu: (visible: boolean) => {
      if (visible) {
        expect(screen.getByRole("listbox")).toBeInTheDocument();
      } else {
        expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
      }
    },
    expectGroupCount: (count: number) => {
      expect(
        screen.queryAllByRole("option", { name: /Option group/ })
      ).toHaveLength(count);
    },
    expectOptionCount: (count: number) => {
      // FIXME find a way to target options without excluding optiongroups (maybe a negative regex ?)
      const optionGroupCount = screen.queryAllByRole("option", {
        name: /Option group/,
      }).length;
      expect(screen.queryAllByRole("option")).toHaveLength(
        count + optionGroupCount
      );
    },
    expectChipCount: (count: number) => {
      // eslint-disable-next-line testing-library/no-node-access
      const chips = wrapper.container.querySelectorAll("span[class^=ds-chip]");
      expect(chips).toHaveLength(count);
    },
  };
};

describe("ComboBox component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    renderComboBox({
      options,
      "data-testid": "combobox",
    });
    expect(screen.getByTestId("combobox")).toBeInTheDocument();
  });

  it("allows string value for single mode", () => {
    const { input } = renderComboBox({ options, value: "rust" });
    expect(input).toHaveValue("Rust");
  });

  it("allows object value for single mode", () => {
    const { input } = renderComboBox({ options, value: options[0] });
    expect(input).toHaveValue("Rust");
  });

  it("allows array of string value for multiple mode", () => {
    const { expectChipCount } = renderComboBox({
      options,
      multiple: true,
      value: ["Rust", "Kotlin"],
    });
    expectChipCount(2);
  });

  it("allows array of object value for multiple mode", () => {
    const { expectChipCount } = renderComboBox({
      options,
      multiple: true,
      value: [options[0], options[2]],
    });
    expectChipCount(2);
  });

  it("open menu on click on input", () => {
    const onChange = jest.fn();
    const { clickOnToggleButton, focusWithMouse, expectMenu, input } =
      renderComboBox({
        options,
        onChange,
      });

    // open menu
    focusWithMouse();
    expectMenu(true);
    clickOnToggleButton();
    expectMenu(false);
    expect(input).toHaveValue("");
    expect(onChange).toHaveBeenCalledTimes(0);
  });

  it("does not select value on blur", async () => {
    const onChange = jest.fn();
    const { clickOnToggleButton, expectMenu, input } = renderComboBox({
      options,
      onChange,
    });

    // open menu
    clickOnToggleButton();
    expectMenu(true);
    await act(async () => {
      input.blur();
    });
    expectMenu(false);
    expect(input).toHaveValue("");
    expect(onChange).toHaveBeenCalledTimes(0);
  });

  it("Filter list of options when using backspace", async () => {
    const onChange = jest.fn();
    const {
      clickOnToggleButton,
      expectMenu,
      expectOptionCount,
      getOption,
      input,
    } = renderComboBox({ options, onChange });

    // open menu
    clickOnToggleButton();
    expectMenu(true);
    fireEvent.click(getOption("Elm"));
    expect(onChange).toHaveBeenCalledTimes(1);
    await userEvent.type(input, "{backSpace}");
    expectOptionCount(2);
  });

  it("calls onChange handler when value changes", () => {
    const onChange = jest.fn();
    const { clickOnToggleButton, expectMenu, getOption, input } =
      renderComboBox({ options, onChange });

    // no initial call on first render
    expect(onChange).toHaveBeenCalledTimes(0);

    // select first value
    clickOnToggleButton();
    expectMenu(true);
    fireEvent.click(getOption("Rust"));
    expect(input).toHaveValue("Rust");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith(options[0]);
  });

  it("allows selecting enabled options", async () => {
    const onChange = jest.fn();
    const {
      clearInput,
      clickOnToggleButton,
      expectMenu,
      expectOptionCount,
      getOption,
      input,
    } = renderComboBox({ options, onChange });

    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(6);

    // Click on disabled option do nothing
    fireEvent.click(getOption("JavaScript"));
    expectMenu(true);
    expect(input).not.toHaveValue("JavaScript");
    expect(onChange).toHaveBeenCalledTimes(0);

    // keyboard arrow navigation skip over disabled option
    // FIXME should require only 3x arrowdown as first option should have focus already ?
    await userEvent.type(
      input,
      "{arrowDown}{arrowDown}{arrowDown}{arrowDown}{enter}"
    );
    expectMenu(false);
    expect(input).toHaveValue("Elm");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(options[4]);

    // enabled option close menu and calls onChange
    clearInput();
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith("");
    fireEvent.click(getOption("Rust"));
    expectMenu(false);
    expect(input).toHaveValue("Rust");
    expect(onChange).toHaveBeenCalledTimes(3);
    expect(onChange).toHaveBeenLastCalledWith(options[0]);

    // clear input calls onChange and opens menu
    clearInput();
    expect(onChange).toHaveBeenCalledTimes(4);
    expect(onChange).toHaveBeenLastCalledWith("");
    expectMenu(true);
    expectOptionCount(6);

    // clicking another option finally works
    fireEvent.click(getOption("Elm"));
    expectMenu(false);
    expect(input).toHaveValue("Elm");
    expect(onChange).toHaveBeenCalledTimes(5);
    expect(onChange).toHaveBeenLastCalledWith(options[4]);
  });

  it("keeps cursor position when typing in the middle of selected value", async () => {
    const onChange = jest.fn();
    const { clickOnToggleButton, expectMenu, getOption, input } =
      renderComboBox({ options, onChange });

    clickOnToggleButton();
    expectMenu(true);
    fireEvent.click(getOption("Rust"));
    expect(input).toHaveValue("Rust");

    input.focus();
    input.setSelectionRange(2, 2);
    await userEvent.type(input, "aa", {
      initialSelectionStart: 2,
      initialSelectionEnd: 2,
    });

    expect(input).toHaveValue("Ruaast");
    expect(input.selectionStart).toEqual(4);
  });

  it("allows selecting multiple options", () => {
    const onChange = jest.fn();
    const {
      clickOnRemove,
      clickOnToggleButton,
      expectMenu,
      expectOptionCount,
      expectChipCount,
      getOption,
      input,
    } = renderComboBox({ options, onChange, multiple: true });

    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(6);

    // select options
    fireEvent.click(getOption("Rust"));
    expectMenu(true);
    expectChipCount(1);
    fireEvent.click(getOption("Elm"));
    expectChipCount(2);
    expect(input).toHaveValue("");
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith([options[0], options[4]]);
    clickOnToggleButton();
    expectMenu(false);

    // delete options
    clickOnRemove("Rust");
    expect(onChange).toHaveBeenCalledTimes(3);
    expect(onChange).toHaveBeenLastCalledWith([options[4]]);
    clickOnRemove("Elm");
    expect(onChange).toHaveBeenCalledTimes(4);
    expect(onChange).toHaveBeenLastCalledWith([]);
  });

  it("allows selecting multiple options using checkbox", () => {
    const onChange = jest.fn();
    const {
      clickOnToggleButton,
      expectMenu,
      expectOptionCount,
      expectChipCount,
      getOptionByIdx,
      input,
    } = renderComboBox({ options, onChange, multiple: true });

    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(6);

    // select options
    fireEvent.click(getOptionByIdx(0)); //click the checkbox
    expectMenu(true);
    expectChipCount(1);
    expect(input).toHaveValue("");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith([options[0]]);

    fireEvent.click(getOptionByIdx(0)); //unclick the checkbox
    expectChipCount(0);
    expect(onChange).toHaveBeenLastCalledWith([]);
    clickOnToggleButton();
    expectMenu(false);
  });

  it("filter options when typing", async () => {
    const onChange = jest.fn();
    const extendedOptions = [
      ...options,
      { label: "91 - CHARTS", value: "91" },
      {
        label: "00 - GENERAL - TECHNICAL INFORMATION WEIGHT AND CG",
        value: "00",
      },
    ];
    const {
      clearInput,
      clickOnToggleButton,
      expectMenu,
      expectOptionCount,
      input,
    } = renderComboBox({ options: extendedOptions, onChange, value: "rust" });

    clickOnToggleButton();
    expectMenu(true);
    // unfiltered options with active value
    expectOptionCount(8);

    // filtered options when typing
    clearInput();
    await userEvent.type(input, "el");
    expectOptionCount(2);

    // unfiltered options when clearing input
    clearInput();
    expectOptionCount(8);

    // another case of filtered options
    await userEvent.type(input, "char");
    expectOptionCount(1);
  });

  it("remove multiple options with backspace", async () => {
    const onChange = jest.fn();
    const { clickOnToggleButton, getOption, input } = renderComboBox({
      options,
      onChange,
      multiple: true,
    });

    clickOnToggleButton();
    fireEvent.click(getOption("Rust"));
    fireEvent.click(getOption("Elm"));
    clickOnToggleButton();
    expect(onChange).toHaveBeenCalledTimes(2);

    // delete options with back space
    await userEvent.type(input, "{backspace}");
    expect(onChange).toHaveBeenCalledTimes(3);
    expect(onChange).toHaveBeenLastCalledWith([options[0]]);
    await userEvent.type(input, "{backspace}");
    expect(onChange).toHaveBeenCalledTimes(4);
    expect(onChange).toHaveBeenLastCalledWith([]);
  });

  it("allow to customize chip labels", () => {
    renderComboBox({
      getChipLabel: (option: any) => "custom label",
      options,
      multiple: true,
      value: [options[0], options[2]],
    });
    expect(screen.getAllByText("custom label")).toHaveLength(2);
  });

  it("allows to change value programmatically", () => {
    const onChange = jest.fn();
    const { input, rerender } = renderComboBox({
      options,
      onChange,
      value: "Elm",
    });

    renderComboBox({ options, onChange, value: "" }, rerender);
    expect(input).toHaveValue("");

    renderComboBox({ options, onChange, value: "Rust" }, rerender);
    expect(input).toHaveValue("Rust");
  });

  it("allows to change options programmatically", () => {
    const { clickOnToggleButton, expectMenu, expectOptionCount, rerender } =
      renderComboBox({
        options,
      });

    const alternativeOptions = [
      { label: "Ruby", value: "ruby" },
      { label: "SmallTalk", value: "smalltalk" },
    ];

    renderComboBox({ options: alternativeOptions }, rerender);
    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(2);
    expect(screen.queryByRole("option", { name: /Ruby/ })).toBeVisible();
    expect(screen.queryByRole("option", { name: /SmallTalk/ })).toBeVisible();
    clickOnToggleButton();
    expectMenu(false);

    renderComboBox({ options }, rerender);
    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(6);
  });

  it("allows clearing single value", () => {
    const onChange = jest.fn();
    const { clear, input } = renderComboBox({
      options,
      onChange,
      defaultValue: "Elm",
    });

    clear();
    expect(input).toHaveValue("");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith("");
  });

  it("allows clearing multiple value", () => {
    const onChange = jest.fn();
    const { clear, input } = renderComboBox({
      multiple: true,
      options,
      onChange,
      defaultValue: ["Elm", "Elixir"],
    });

    clear();
    expect(input).toHaveValue("");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith([]);
  });

  it("allow creating options from empty list (single)", async () => {
    const onChange = jest.fn();
    const onCreate = jest.fn();
    const { clear, expectOptionCount, getOption, input } = renderComboBox({
      creatable: true,
      onChange,
      onCreate,
    });

    // add "test" option
    await userEvent.type(input, "test");
    expectOptionCount(1);
    fireEvent.click(getOption('Add "test"'));
    expect(onCreate).toHaveBeenCalledTimes(1);
    expect(onCreate).toHaveBeenLastCalledWith("test");
    expect(onChange).toHaveBeenCalledTimes(0);

    // clear
    clear();
    expect(onChange).toHaveBeenCalledTimes(1);

    // add "test2" option
    await userEvent.type(input, "test2");
    expectOptionCount(1);
    fireEvent.click(getOption('Add "test2"'));
    expect(onCreate).toHaveBeenCalledTimes(2);
    expect(onCreate).toHaveBeenLastCalledWith("test2");
    expect(onChange).toHaveBeenCalledTimes(1);
  });

  it("allow creating options from empty list (multiple)", async () => {
    const onChange = jest.fn();
    const onCreate = jest.fn();
    const { expectOptionCount, getOption, input } = renderComboBox({
      creatable: true,
      multiple: true,
      onChange,
      onCreate,
    });

    // add "test" option
    await userEvent.type(input, "test");
    expectOptionCount(1);
    fireEvent.click(getOption('Add "test"'));
    expect(onCreate).toHaveBeenCalledTimes(1);
    expect(onCreate).toHaveBeenLastCalledWith("test");
    expect(onChange).toHaveBeenCalledTimes(0);

    // add "test2" option
    await userEvent.type(input, "test2");
    expectOptionCount(1);
    fireEvent.click(getOption('Add "test2"'));
    expect(onCreate).toHaveBeenCalledTimes(2);
    expect(onCreate).toHaveBeenLastCalledWith("test2");
    expect(onChange).toHaveBeenCalledTimes(0);
  });

  it("allow creating options uncontrolled", async () => {
    const onChange = jest.fn();
    const { clear, expectOptionCount, getOption, input } = renderComboBox({
      creatable: true,
      onChange,
    });

    // add "test" option
    await userEvent.type(input, "test");
    expectOptionCount(1);
    fireEvent.click(getOption('Add "test"'));
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith({ value: "test", label: "test" });

    // clear
    clear();
    expect(onChange).toHaveBeenCalledTimes(2);

    // add "test2" option
    await userEvent.type(input, "test2");
    expectOptionCount(1);
    fireEvent.click(getOption('Add "test2"'));
    expect(onChange).toHaveBeenCalledTimes(3);
    expect(onChange).toHaveBeenLastCalledWith({
      value: "test2",
      label: "test2",
    });
  });

  it("allow creating options with predefined list", async () => {
    const onChange = jest.fn();
    const onCreate = jest.fn();
    const { expectOptionCount, getOption, input } = renderComboBox({
      creatable: true,
      onChange,
      onCreate,
      options,
    });

    await userEvent.type(input, "test");
    expectOptionCount(1);

    fireEvent.click(getOption('Add "test"'));
    expect(onCreate).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledTimes(0);
  });

  it("allow creating options with custom format", async () => {
    let options = [
      { value: "one", label: "One", prefix: "test" },
      { value: "two", label: "Two", prefix: "test" },
    ];

    const onChange = jest.fn();
    const onCreate = (value: string) => {
      const newOption = {
        value: value,
        label: value.toUpperCase(),
        prefix: "test",
      };
      options.push(newOption);
      return newOption;
    };

    const {
      clear,
      clickOnToggleButton,
      expectOptionCount,
      expectMenu,
      getOption,
      input,
      rerender,
    } = renderComboBox({
      creatable: true,
      onChange,
      onCreate,
      options,
    });

    await userEvent.type(input, "three");
    expectOptionCount(1);
    fireEvent.click(getOption('Add "three"'));

    renderComboBox({ creatable: true, onChange, onCreate, options }, rerender);
    clear();
    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(3);

    // Click on disabled option do nothing
    fireEvent.click(getOption("THREE"));
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith({
      value: "three",
      label: "THREE",
      prefix: "test",
    });
  });

  it("allow option label with line breaks #1312", async () => {
    const opts = [
      "123AL",
      "321AL\n322AL 322BL 322CL\n323AL 323AR\n324AT 325AL 325AR 325BL 325BR 325CL 325CR 325DL 325DR 325EL 325ER",
      "321AL\n322BL\n324AT",
      "321AL 322BL 323AL 323AR 325AL 325AR",
    ];
    const onChange = jest.fn();
    const { clickOnToggleButton, expectMenu, expectOptionCount, input } =
      renderComboBox({ options: opts, onChange });

    // open menu
    clickOnToggleButton();
    expectMenu(true);

    // select second option with keyboard
    await userEvent.type(input, "321");
    expectOptionCount(3);
    await userEvent.type(input, "{arrowDown}{enter}");
    expectMenu(false);
    expect(input).toHaveValue(
      "321AL 322AL 322BL 322CL 323AL 323AR 324AT 325AL 325AR 325BL 325BR 325CL 325CR 325DL 325DR 325EL 325ER"
    );
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(opts[1]);

    // click outside should not trigger onChange
    await userEvent.click(document.body);
    expect(onChange).toHaveBeenCalledTimes(1);
  });

  it("allow to use virtualization", () => {
    const options: any[] = [...Array(100).keys()].map((v, i) => ({
      label: `Option ${i}`,
      value: `option${i}`,
    }));
    const { clickOnToggleButton, expectMenu, expectOptionCount } =
      renderComboBox({
        options,
        allowVirtualization: true,
        virtualizationOptions: {
          rowsVisible: 6,
          overscanCount: 2,
        },
      });
    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(8); //including overscan count
    expect(screen.queryByRole("option", { name: /Option 8/ })).toBeNull();
  });

  it("hide remove icon button on disabled options #1323", () => {
    const { expectChipCount } = renderComboBox({
      multiple: true,
      hideClearOnDisabled: true,
      options: [...options, { label: "CPP", value: "cpp", disabled: true }],
      value: ["CPP", "JavaScript", "Kotlin"],
    });
    expectChipCount(3);
    expect(screen.queryAllByRole("button", { name: "Remove" })).toHaveLength(1);
  });

  it("allow to set default input value", () => {
    const onChange = jest.fn();
    const { clearInput, clickOnToggleButton, expectMenu, expectOptionCount } =
      renderComboBox({ options, onChange, defaultInputValue: "el" });

    // prefiltered options based on inputValue
    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(2);

    // all options visible after clearing input
    clearInput();
    expectOptionCount(6);
    expect(onChange).toHaveBeenCalledTimes(0);
  });

  it("allow to keep input on select in multiple mode", () => {
    const onChange = jest.fn();
    const {
      clickOnToggleButton,
      expectChipCount,
      expectMenu,
      expectOptionCount,
      getOption,
    } = renderComboBox({
      multiple: true,
      keepInputOnSelect: true,
      options,
      onChange,
      defaultInputValue: "el",
    });

    // prefiltered options based on inputValue
    clickOnToggleButton();
    expectMenu(true);
    expectOptionCount(2);

    // select both filtered options
    fireEvent.click(getOption("Elm"));
    expect(onChange).toHaveBeenCalledTimes(1);
    expectOptionCount(1);

    fireEvent.click(getOption("Elixir"));
    expect(onChange).toHaveBeenCalledTimes(2);
    expectChipCount(2);
    expectMenu(true);
    expectOptionCount(0);
  });

  it("allow grouping options", async () => {
    const onChange = jest.fn();
    const {
      clickOnToggleButton,
      expectChipCount,
      expectGroupCount,
      expectMenu,
      expectOptionCount,
      input,
    } = renderComboBox({
      groupBy: (option: ComboBoxDefaultOption) => option.label.charAt(0),
      multiple: true,
      options,
      onChange,
    });

    clickOnToggleButton();
    expectMenu(true);
    expectGroupCount(5);
    expectOptionCount(6);

    // options are reordered by groups > Elm is 3rd instead of 5th
    await userEvent.type(input, "{arrowDown}{arrowDown}{arrowDown}{enter}");
    expectChipCount(1);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith([options[4]]);

    // remove selected option
    await userEvent.type(input, "{backspace}");
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith([]);

    // filter list showing only one group
    await userEvent.type(input, "el");
    expectGroupCount(1);
    expectOptionCount(2);
  });

  it("Touch interactions - prevents input blur on touch start within container", () => {
    const { input, toggleButton } = renderComboBox({ options });
    // 1. Focus the input
    input.focus();
    expect(input).toHaveFocus();
    // 2. Simulate touching the toggle button (part of the container, but not the input)
    //    code checks: if (target.id !== id) preventDefault()
    fireEvent.touchStart(toggleButton);
    // 3. The input should remain focused because preventDefault() stops the blur
    expect(input).toHaveFocus();
  });

  it("IME interactions - keeps composed text visible while composing", async () => {
    const { clickOnToggleButton, expectOptionCount, input } = renderComboBox({
      options,
    });

    await clickOnToggleButton();
    fireEvent.compositionStart(input);
    fireEvent.change(input, { target: { value: "el" } });
    expect(input).toHaveValue("el");

    fireEvent.compositionEnd(input);
    expectOptionCount(2);
  });

  it("IME interactions - ignores Enter selection while composing", async () => {
    const onChange = jest.fn();
    const { clickOnToggleButton, expectMenu, input } = renderComboBox({
      options,
      onChange,
    });

    await clickOnToggleButton();
    expectMenu(true);

    fireEvent.compositionStart(input);
    fireEvent.keyDown(input, {
      key: "Enter",
      keyCode: 229,
      which: 229,
      isComposing: true,
    });

    expect(onChange).toHaveBeenCalledTimes(0);
    expectMenu(true);
  });

  it("IME interactions - ignores IME keydown navigation events", async () => {
    const onChange = jest.fn();
    const { clickOnToggleButton, expectMenu, input } = renderComboBox({
      options,
      onChange,
    });

    await clickOnToggleButton();
    expectMenu(true);

    // Trigger the IME event path used by Downshift stateReducer guard.
    const imeProcessEvent = createEvent.keyDown(input, {
      key: "Process",
      keyCode: 229,
      which: 229,
    });
    fireEvent(input, imeProcessEvent);
    fireEvent.keyDown(input, { key: "Enter", keyCode: 13, which: 13 });

    // Enter should still select the first highlighted option.
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(options[0]);
  });

  it("Keyboard interactions - stops Escape propagation only when menu is open", async () => {
    const onDocumentKeyDown = jest.fn();
    document.addEventListener("keydown", onDocumentKeyDown);

    const { clickOnToggleButton, input } = renderComboBox({ options });

    // Closed menu: Escape should propagate.
    fireEvent.keyDown(input, { key: "Escape", keyCode: 27, which: 27 });
    expect(onDocumentKeyDown).toHaveBeenCalledTimes(1);

    await clickOnToggleButton();
    fireEvent.keyDown(input, { key: "Escape", keyCode: 27, which: 27 });

    // Open menu: Escape should be stopped to avoid closing parent dialogs.
    expect(onDocumentKeyDown).toHaveBeenCalledTimes(1);

    document.removeEventListener("keydown", onDocumentKeyDown);
  });

  it("Touch interactions - selects an option on touch", async () => {
    const { clickOnToggleButton, getOption, input } = renderComboBox({
      options,
    });
    clickOnToggleButton();
    const optionToSelect = getOption("Rust");
    const user = userEvent.setup();
    await user.pointer({ keys: "[TouchA]", target: optionToSelect });
    expect(input).toHaveValue("Rust");
  });

  // To make sure that the menu doesn't close when the user is interacting with the menu.
  it("Touch interactions - prevents menu from closing on blur during active touch", async () => {
    const { clickOnToggleButton, expectMenu, input } = renderComboBox({
      options,
    });

    // 1. Open the menu normally
    await clickOnToggleButton();
    expectMenu(true);

    const menu = screen.getByRole("listbox");

    // Simulate the user touching the screen
    fireEvent.touchStart(menu);

    // Simulate the blur event that Downshift fires when focus leaves the input
    fireEvent.blur(input);

    // Assert that the menu is STILL open because our stateReducer blocked the blur
    expectMenu(true);

    // End the first touch so we can start fresh for the next scenario
    fireEvent.touchEnd(menu);
  });

  it("Touch interactions - does not select option if touch ends outside an option", async () => {
    const onChange = jest.fn();
    const { clickOnToggleButton, getOption, input } = renderComboBox({
      options,
      onChange,
    });

    const user = userEvent.setup();
    clickOnToggleButton();
    const optionToSelect = getOption("Rust");

    // Simulate the touch drag interaction
    await user.pointer([
      // Step 1: Touch the screen at the starting element that is the option from the menu, assigning a name 'TouchA'
      { keys: "[TouchA>]", target: optionToSelect },
      // Step 2: Move the touch pointer (named 'TouchA') to the ending element that is the combobox/input, which is outside the menu
      { pointerName: "TouchA", target: input },
      // Step 3: Release the touch pointer at the final position
      { keys: "[/TouchA]" },
    ]);

    // Should NOT have triggered a change. That means since we have left the touch input outside the option, it should not select the option.
    expect(onChange).not.toHaveBeenCalled();
  });

  it("does not throw error, when disabled and creatable", async () => {
    // this test was added in response to the issue #3160,
    // when creatable, oncreate, options= one option with disabled:true
    const onChange = jest.fn();
    const onCreate = jest.fn();
    const { focusWithMouse, expectMenu, expectOptionCount } = renderComboBox({
      options: [options[3]],
      onChange,
      creatable: true,
      onCreate,
    });

    focusWithMouse();
    expectMenu(true);
    expectOptionCount(1);
  });
});
